void PndRhoTupleQA::qaPoca(TString pre, RhoCandidate *c, RhoTuple *n)
{
  if (n == nullptr)
    return;

  // *** simple vtx finder
  TVector3 vtx, altvtx, primvtx;
  double qavtx = fVtxPoca->GetPocaVtx(vtx, c);

  // *** determine poca of rest of tracks
  RhoCandList l;
  fAnalysis->FillList(l, "Charged");
  if (fVtxPoca->GetPocaVtx(primvtx, l) > 998.)
    primvtx.SetXYZ(0., 0., 0.);

  l.RemoveFamily(c);

  if (l.GetLength() > 1)
    fVtxPoca->GetPocaVtx(altvtx, l);
  else
    altvtx = primvtx;

  double dist = 999.;
  if (altvtx.Mag() > 0.)
    dist = (vtx - altvtx).Mag();

  // *** store QA info
  n->Column(pre + "pocvx", (Float_t)vtx.X(), 0.0f);
  n->Column(pre + "pocvy", (Float_t)vtx.Y(), 0.0f);
  n->Column(pre + "pocvz", (Float_t)vtx.Z(), 0.0f);
  n->Column(pre + "altvx", (Float_t)altvtx.X(), 0.0f);
  n->Column(pre + "altvy", (Float_t)altvtx.Y(), 0.0f);
  n->Column(pre + "altvz", (Float_t)altvtx.Z(), 0.0f);
  n->Column(pre + "pocmag", (Float_t)vtx.Mag(), 0.0f);
  n->Column(pre + "pocqa", (Float_t)qavtx, 0.0f);
  n->Column(pre + "pocdist", (Float_t)dist, 0.0f);
  n->Column(pre + "pocctau", (Float_t)(dist * c->M() / c->P()), 0.0f); // decay length
}

Double_t RhoVtxPoca::GetPoca(TVector3 &vertex, RhoCandidate *a, RhoCandidate *b)
{
  // Decide which POCA algorithm to use

  if (fabs(a->Charge()) > 1e-6 && fabs(b->Charge()) > 1e-6)
    return GetPocaTwoCharged(vertex, a, b);
  else if (fabs(a->Charge()) < 1e-6 && fabs(b->Charge()) < 1e-6)
    return GetPocaTwoNeutral(vertex, a, b);
  else if (fabs(a->Charge()) < 1e-6 || fabs(b->Charge()) < 1e-6)
    return GetPocaChargedToNeutral(vertex, a, b);
  else
    return -99999.;
}

Double_t RhoVtxPoca::GetPoca(TVector3& vertex,RhoCandidate* a, RhoCandidate* b)
{
  // Decide which POCA algorithm to use
  
  if      (fabs(a->Charge())>1e-6 && fabs(b->Charge())>1e-6) return GetPocaTwoCharged(vertex, a, b);
  else if (fabs(a->Charge())<1e-6 && fabs(b->Charge())<1e-6) return GetPocaTwoNeutral(vertex, a, b);
  else if (fabs(a->Charge())<1e-6 || fabs(b->Charge())<1e-6) return GetPocaChargedToNeutral(vertex, a, b);
  else return -99999.;
}

