double PndSoftTriggerTask::GetPocaVtx(RhoCandidate *c, double &dist, double &ctau)
{
  // *** simple vtx finder
  TVector3 vtx, altvtx, primvtx;
  double qavtx = fPocaVertexer->GetPocaVtx(vtx, c);

  // *** determine poca of rest of tracks
  RhoCandList l;
  fAnalysis->FillList(l, "Charged");

  // remove c's daughters from charged tracks list
  l.RemoveFamily(c);

  // if at least 2 tracks left, compute the poca vertex of the residual tracks
  if (l.GetLength() > 1)
    fPocaVertexer->GetPocaVtx(altvtx, l);
  else
    altvtx = fPrimVtx; // else use the primary vtx found before

  dist = 999.;
  // *** if vertex of either all charged or residual tracks was found, compute distance and ctau
  if (altvtx.Mag() > 0.)
    dist = (vtx - altvtx).Mag();

  ctau = dist * c->M() / c->P();

  return qavtx;
}

TVector2 PndTrkTools::ComputePocaToLineOnCircle(double m, double q, double xc, double yc, double R) {
  // there are two points where the line is tangent
  // to the circle
  double xi1, yi1, xi2, yi2;
  ComputeLinePointOfTangenceOnACircle(m, xc, yc, R, xi1, yi1, xi2, yi2);

  // I want the nearest to the line
  double xp = 999, yp = -999;
  fabs(yi1 - (m * xi1 + q)) < fabs(yi2 - (m * xi2 + q)) ? (xp = xi1, yp = yi1) : (xp = xi2 , yp = yi2);

  return TVector2(xp, yp);
}

double PndSoftTriggerTask::GetPocaVtx(RhoCandidate* c, double &dist, double &ctau)
{
	// *** simple vtx finder
	TVector3 vtx, altvtx, primvtx;
	double qavtx = fPocaVertexer->GetPocaVtx(vtx, c);
	
	// *** determine poca of rest of tracks
	RhoCandList l;
	fAnalysis->FillList(l, "Charged");
	
	// remove c's daughters from charged tracks list
	l.RemoveFamily(c);

	// if at least 2 tracks left, compute the poca vertex of the residual tracks
	if (l.GetLength()>1) fPocaVertexer->GetPocaVtx(altvtx, l);
	else altvtx = fPrimVtx; // else use the primary vtx found before
	
	dist = 999.;
	// *** if vertex of either all charged or residual tracks was found, compute distance and ctau
	if (altvtx.Mag()>0.) dist = (vtx-altvtx).Mag();
	
	ctau = dist*c->M()/c->P();

	return qavtx;
}

