InitStatus PndPidCorrelator::Init() {

  //  cout << "InitStatus PndPidCorrelator::Init()" << endl;

  FairRootManager *fManager =FairRootManager::Instance();

  if (fUseFittedVertex && !fEventVertexFileName.IsNull()) {
    TDirectory* savedDirectory = gDirectory;
    fEventVertexFile = TFile::Open(fEventVertexFileName, "READ");
    if (savedDirectory) savedDirectory->cd();
    if (!fEventVertexFile || fEventVertexFile->IsZombie()) {
      cout << "-E- PndPidCorrelator::Init: Cannot open event POCA file "
           << fEventVertexFileName << endl;
      return kERROR;
    }
    fEventVertexTree = dynamic_cast<TTree*>(fEventVertexFile->Get("event_poca"));
    if (!fEventVertexTree) {
      cout << "-E- PndPidCorrelator::Init: Tree 'event_poca' is missing in "
           << fEventVertexFileName << endl;
      return kERROR;
    }
    fEventVertexTree->SetBranchAddress("event_id", &fEventVertexId);
    fEventVertexTree->SetBranchAddress("x", &fEventVertexX);
    fEventVertexTree->SetBranchAddress("y", &fEventVertexY);
    fEventVertexTree->SetBranchAddress("z", &fEventVertexZ);
    fEventVertexTree->SetBranchAddress("valid", &fEventVertexValid);
    cout << "-I- PndPidCorrelator::Init: Using event-level POCA vertices from "
         << fEventVertexFileName << endl;
  }

  fTrack = dynamic_cast<TClonesArray *> (fManager->GetObject(fTrackBranch));
  if ( ! fTrack ) {
    cout << "-I- PndPidCorrelator::Init: No PndTrack array!" << endl;
    return kERROR;
  }

  // Get the MCTrack array
  fMcTrackPro = dynamic_cast<TClonesArray *> (fManager->GetObject("MCTrack"));
  if (!fMcTrackPro) {
      cout << "MCTrack branch not found, cannot use MC truth for propagation!" << endl;
      fUseMcTruthForTarget = kFALSE; // Force the flag to false if data is not available
  }

  //  if (fTrackIDBranch!="")
  //    {
  //      fTrackID = dynamic_cast<TClonesArray *> (fManager->GetObject(fTrackIDBranch));
  //      if ( ! fTrackID ) {
  //	cout << "-I- PndPidCorrelator::Init: No PndTrackID array! Switching MC propagation OFF" << endl;
  //	fTrackIDBranch = "";
  //      }
  //    }

  if (fTrackBranch2!="")
  {
    fTrack2 = dynamic_cast<TClonesArray *> (fManager->GetObject(fTrackBranch2));
    if ( ! fTrack2 ) {
      cout << "-I- PndPidCorrelator::Init: No 2nd PndTrack array!" << endl;
      return kERROR;
    }
  }

  //  if (fTrackIDBranch2!="")
  //    {
  //      fTrackID2 = dynamic_cast<TClonesArray *> (fManager->GetObject(fTrackIDBranch2));
  //      if ( ! fTrackID2 ) {
  //	cout << "-I- PndPidCorrelator::Init: No 2nd PndTrackID array! Switching MC propagation OFF" << endl;
  //	fTrackIDBranch2 = "";
  //      }
  //    }

  // *** STT ***
  if (fSttMode)
  {
    if (fMixMode==kFALSE)
    {
      fSttHit = dynamic_cast<TClonesArray *> ( fManager->GetObject("STTHit"));
      if ( fSttHit )
      {
        cout << "-I- PndPidCorrelator::Init: Using STTHit" << endl;
        fSttMode = 2;
      }
      else
      {
        cout << "-W- PndPidCorrelator::Init: No STT hits array! Switching STT OFF" << endl;
        fSttMode = 0;
      }
    }
    else
    {
      fSttHit = dynamic_cast<TClonesArray *> (fManager->GetObject("STTHitMix"));
      if ( fSttHit )
      {
        cout << "-I- PndPidCorrelator::Init: Using STTHitMix" << endl;
        fSttMode = 2;
      }
      else
      {
        cout << "-W- PndPidCorrelator::Init: No STT hits mix array! Switching STT OFF" << endl;
        fSttMode = 0;
      }
    }
  }

