  // corr->SetBackPropagate(kFALSE);

  // -----   Bremsstrahlung Correction ----------------------
  fRun->AddTask(new PndPidBremCorrector());

  // -----   MC Cloner   ------------------------------------
  PndMcCloner *clone = NULL;
  fRun->AddTask(clone = new PndMcCloner());
