  clone->SetCleanMc();

  // -----   Classifiers   ----------------------------------
  fRun->AddTask(new PndPidIdealAssociatorTask());
  fRun->AddTask(new PndPidMvdAssociatorTask());
  fRun->AddTask(new PndPidMdtHCAssociatorTask());
