  fRun->AddTask(new PndPidEmcBayesAssociatorTask());

  fRun->AddTask(new PndPidSciTAssociatorTask());

  fRun->AddTask(new PndPidFtofAssociatorTask());

  if ((!fOptions.Contains("day1"))) {
    fRun->AddTask(new PndPidRichAssociatorTask());
  }

  // -----   Intialise and run   --------------------------------------------
  PndEmcMapper::Init(1);
  fRun->Init();
  fRun->Run(0, nEvents);
  fRun->Finish();
  return 0;
}

