#ifndef PNDLMDDPMMTMODEL1D_H_
#define PNDLMDDPMMTMODEL1D_H_

#include "LumiFitStructs.h"
#include "core/Model1D.h"

/**
 * \brief This class is the base of lumi models such as #PndLmdLumiModelROOT and
 * #PndLmdLumiModelRooFit which can be fitted to #PndLmdData objects.
 *
 * The reason for a model base class is a common model description in all
 * different fit implementations (ROOT and RooFit etc). The DPM model
 * description can be found in the #evaluate() function.
 *
 * Also this class contains all the necessary handles for the only degree of
 * freedom, the acceptance description (see #PndLmdAcceptance), which is
 * required for applying an acceptance correction. The acceptance description
 * can of course differ depending on its binning, data size, etc. Hence usually
 * more than one model instance can be active.
 */
class PndLmdDPMMTModel1D : public Model1D {
protected:
  // constants
  mydouble pi;
  mydouble hbarc2;
  mydouble alpha;
  mydouble M;
  mydouble alpha_squared_4pi;
  mydouble one_over_16pi_hbarc2;

  /**
   * References to the values of the parameters used in the DPM description
   * of the cross section that are constants or are actually parameters in
   * the fit
   */
  // strictly fixed parameters
  std::shared_ptr<ModelPar> p_lab;
  std::shared_ptr<ModelPar> luminosity;
  std::shared_ptr<ModelPar> E_lab;
  std::shared_ptr<ModelPar> S;
  std::shared_ptr<ModelPar> pcm2;
  std::shared_ptr<ModelPar> gamma;
  std::shared_ptr<ModelPar> beta;
  std::shared_ptr<ModelPar> beta_lab_cms;
  // possibly free fit parameters
  std::shared_ptr<ModelPar> sigma_tot;
  std::shared_ptr<ModelPar> b;
  std::shared_ptr<ModelPar> rho;
  std::shared_ptr<ModelPar> A1;
  std::shared_ptr<ModelPar> A2;
  std::shared_ptr<ModelPar> A3;
  std::shared_ptr<ModelPar> T1;
  std::shared_ptr<ModelPar> T2;

  // function pointer used to switch between different algorithms for
  // interpolation
  typedef mydouble (PndLmdDPMMTModel1D::*function)(const mydouble *x) const;

  function model_func;

  /**
   *  initializes the above parameters of the DPM cross section that are
   *  absolutely fixed (so not dependent on the beam momentum for example)
   */
  void init();

  void updateDomainFromPars(mydouble *par);

public:
  LumiFit::DPMElasticParts elastic_type;

  /**
   * In the constructor that creates a fully defined pure signal cross section
   * model of LMD
   * @param name_ is the name of the model. Make sure that it is unique.
   */
  PndLmdDPMMTModel1D(std::string name_, LumiFit::DPMElasticParts elastic_type_);

  ~PndLmdDPMMTModel1D();

  virtual void initModelParameters();

  mydouble getDelta(const mydouble t) const;

  mydouble getProtonDipoleFormFactor(const mydouble t) const;

  mydouble getRawCoulombPart(const mydouble *x) const;

  mydouble getRawInterferencePart(const mydouble *x) const;

  mydouble getRawHadronicPart(const mydouble *x) const;

  mydouble getRawRhoBSigtotHadronicPart(const mydouble *x) const;

  mydouble getRawFullElastic(const mydouble *x) const;

  mydouble getRawRhoBSigtotFullElastic(const mydouble *x) const;

  virtual mydouble eval(const mydouble *x) const;

  virtual void updateDomain();
};

#endif /* PNDLMDDPMMTMODEL1D_H_ */

PndLmdDPMMTModel1D::PndLmdDPMMTModel1D(std::string name_,
                                       LumiFit::DPMElasticParts elastic_type_)
    : Model1D(name_) {

  elastic_type = elastic_type_;
  if (elastic_type == LumiFit::COUL) {
    model_func = &PndLmdDPMMTModel1D::getRawCoulombPart;
  } else if (elastic_type == LumiFit::INT) {
    model_func = &PndLmdDPMMTModel1D::getRawInterferencePart;
  } else if (elastic_type == LumiFit::HAD) {
    model_func = &PndLmdDPMMTModel1D::getRawHadronicPart;
  } else if (elastic_type == LumiFit::HAD_RHO_B_SIGTOT) {
    model_func = &PndLmdDPMMTModel1D::getRawRhoBSigtotHadronicPart;
  } else if (elastic_type == LumiFit::ALL_RHO_B_SIGTOT) {
    model_func = &PndLmdDPMMTModel1D::getRawRhoBSigtotFullElastic;
  } else {
    model_func = &PndLmdDPMMTModel1D::getRawFullElastic;
  }

  // here a bunch of parameters, which are constants, will be set
  init();
  initModelParameters();
}

TGraphAsymmErrors *PndLmdPlotter::generateDPMModelPartGraph(
    double plab, LumiFit::DPMElasticParts dpm_elastic_part,
    DataStructs::DimensionRange &plot_range) {

  ModelVisualizationProperties1D vis_prop;
  vis_prop.setPlotRange(plot_range);

  boost::property_tree::ptree model_opt_ptree;
  model_opt_ptree.put("dpm_elastic_parts",
                      LumiFit::DPMElasticPartsToString.at(dpm_elastic_part));
  model_opt_ptree.put("fit_dimension", 1);

  PndLmdAngularData data;
  data.setLabMomentum(plab);

  std::shared_ptr<Model> model =
      model_factory.generateModel(model_opt_ptree, data);
  if (model->init()) {
    std::cout << "Error: not all parameters have been set!" << std::endl;
  }

  TGraphAsymmErrors *model_graph =
      root_plotter.createGraphFromModel1D(model, vis_prop);

  return model_graph;
}

int main(int argc, char *argv[]) {
  bool is_mom_set = false, is_num_events_set = false;
  double momentum = -1.0;
  unsigned int num_events = 0;
  int c;

  while ((c = getopt(argc, argv, "hm:n:")) != -1) {
    switch (c) {
    case 'm':
      momentum = atof(optarg);
      is_mom_set = true;
      break;
    case 'n':
      num_events = atoi(optarg);
      is_num_events_set = true;
      break;
    case '?':
      if (optopt == 'm' || optopt == 'n')
        std::cerr << "Option -" << optopt << " requires an argument."
                  << std::endl;
      else if (isprint(optopt))
        std::cerr << "Unknown option -" << optopt << "." << std::endl;
      else
        std::cerr << "Unknown option character" << optopt << "." << std::endl;
      return 1;
    case 'h':
      displayInfo();
      return 1;
    default:
      return 1;
    }
  }

  if (is_mom_set && is_num_events_set) {
    fitRawDPMElasticData(momentum, num_events);
  } else
    displayInfo();

  return 0;
}

PndLmdDPMAngModel1D::PndLmdDPMAngModel1D(
    std::string name_, LumiFit::DPMElasticParts elastic_type_,
    LumiFit::TransformationOption trafo_type)
    : PndLmdDPMMTModel1D(name_, elastic_type_) {

  initModelParameters();

  if (trafo_type == LumiFit::CORRECT) {
    trafo_func = &PndLmdDPMAngModel1D::getMomentumTransferFromThetaCorrect;
  } else {
    trafo_func = &PndLmdDPMAngModel1D::getMomentumTransferFromThetaApprox;
  }
}

