PndPidCorrelator::PndPidCorrelator(const char *name, const char *title, Bool_t use_default_setup) : FairTask(name), fUseDefaultDetectorSetup(use_default_setup)
{
  fDebugDir = "./";
  fDebugFile = "./pidcorrelator.root";

  if (fUseDefaultDetectorSetup)
    DefaultDetectorSetup();

  fPidChargedCand = new TClonesArray("PndPidCandidate");

  SetTitle(title);
}

PndPidCorrelator::~PndPidCorrelator()
{
  fManager->Write();
  if (fTrackingSystemInfo != nullptr)
    delete fTrackingSystemInfo;
  if (fCalorimeterInfo != nullptr)
    delete fCalorimeterInfo;

  for (UInt_t i = 0; i < fBarrelDetectors.size(); i++) {
    if (fBarrelDetectors.at(i) != nullptr)
      delete fBarrelDetectors.at(i);
  }
  for (UInt_t i = 0; i < fForwardDetectors.size(); i++) {
    if (fForwardDetectors.at(i) != nullptr)
      delete fForwardDetectors.at(i);
  }
}

PndPidCorrelator::PndPidCorrelator(Bool_t use_default_setup) : FairTask(), fUseDefaultDetectorSetup(use_default_setup)
{
  fDebugDir = "./";
  fDebugFile = "./pidcorrelator_DebugOut.root";

  if (fUseDefaultDetectorSetup)
    DefaultDetectorSetup();

  fPidChargedCand = new TClonesArray("PndPidCandidate");
  if (!fHasPrimary) {
    fHasPrimary = kTRUE;
    fDoNeutralCand = kTRUE;
    // TODO: Do we want neutrals for different track hypothesis?
    fPidNeutralCand = new TClonesArray("PndPidCandidate");
  }
}

void PndPidCorrelator::SetPropagator(PndPropagator *propagator)
{
  if (propagator == nullptr) {
    LOG_IF(info, fVerbose > 0) << "PndPidCorrelator::Init(): Using Geane for track propagation";
    fPropagator = new PndGeanePro();
  } else {
    fPropagator = propagator;
  }

  if (!fCorrErrorProp) {
    LOG_IF(info, fVerbose > 1) << "PndPidCorrelator::Init(): Switching OFF error propagation";
    fPropagator->SetPropagateOnlyParameters();
  }
}

