 *      Author: steve
 */

#include "PndLmdAcceptance.h"

ClassImp(PndLmdAcceptance)

    PndLmdAcceptance::PndLmdAcceptance() {
  name = "lmd_acceptance";
  acceptance_1d = 0;
  acceptance_2d = 0;
}

PndLmdAcceptance::PndLmdAcceptance(const PndLmdAcceptance &lmd_acc_data_)
    : PndLmdAbstractData(lmd_acc_data_) {
  if (lmd_acc_data_.getAcceptance1D())
    acceptance_1d = new TEfficiency(*lmd_acc_data_.getAcceptance1D());
  if (lmd_acc_data_.getAcceptance2D())
    acceptance_2d = new TEfficiency(*lmd_acc_data_.getAcceptance2D());
}

PndLmdAcceptance::~PndLmdAcceptance() {}

void PndLmdAcceptance::init1DData() {
  // 1d acceptance
  acceptance_1d =
      new TEfficiency("acc1d", "", primary_dimension.bins,
                      primary_dimension.dimension_range.getRangeLow(),
                      primary_dimension.dimension_range.getRangeHigh());
}

void PndLmdAcceptance::init2DData() {
  // 2d acceptance
  acceptance_2d =
      new TEfficiency("acc2d", "", primary_dimension.bins,
                      primary_dimension.dimension_range.getRangeLow(),
                      primary_dimension.dimension_range.getRangeHigh(),
                      secondary_dimension.bins,
                      secondary_dimension.dimension_range.getRangeLow(),
                      secondary_dimension.dimension_range.getRangeHigh());
}

void PndLmdAcceptance::cloneData(const PndLmdAbstractData &lmd_abs_data) {
  const PndLmdAcceptance *lmd_acc =
      dynamic_cast<const PndLmdAcceptance *>(&lmd_abs_data);
  if (lmd_acc) {
    acceptance_1d = new TEfficiency(*lmd_acc->getAcceptance1D());
    if (getSecondaryDimension().is_active) {
      acceptance_2d = new TEfficiency(*lmd_acc->getAcceptance2D());
    }
  }
}

TEfficiency *PndLmdAcceptance::getAcceptance1D() const { return acceptance_1d; }
TEfficiency *PndLmdAcceptance::getAcceptance2D() const { return acceptance_2d; }

void PndLmdAcceptance::add(const PndLmdAbstractData &lmd_abs_data_addition) {
  const PndLmdAcceptance *lmd_acc_addition =
      dynamic_cast<const PndLmdAcceptance *>(&lmd_abs_data_addition);
  if (lmd_acc_addition) {
    if (getPrimaryDimension().dimension_range ==
        lmd_acc_addition->getPrimaryDimension().dimension_range) {
      setNumEvents(getNumEvents() + lmd_acc_addition->getNumEvents());
      acceptance_1d->Add(*lmd_acc_addition->getAcceptance1D());
      if (getSecondaryDimension().is_active) {
        if (getSecondaryDimension().dimension_range ==
            lmd_acc_addition->getSecondaryDimension().dimension_range) {
          acceptance_2d->Add(*lmd_acc_addition->getAcceptance2D());
        }
      }
    }
  }
}

// acceptance filling methods
void PndLmdAcceptance::addData(bool is_accepted, double primary_value,
                               double secondary_value) {
  acceptance_1d->Fill(is_accepted, primary_value);
  if (secondary_dimension.is_active)
    acceptance_2d->Fill(is_accepted, primary_value, secondary_value);
}

void createLmdFitData(const std::string &input_dir_path,
                      const std::string &filelist_path,
                      const std::string &output_dir_path,
                      const std::string &config_file_url, const double mom,
                      std::string &data_types, int num_events,
                      const double total_elastic_cross_section) {
  std::cout << "Running LmdFit data reader....\n";

  PndLmdRuntimeConfiguration &lmd_runtime_config =
      PndLmdRuntimeConfiguration::Instance();

  // set paths and general infos first
  lmd_runtime_config.setMomentum(mom);
  lmd_runtime_config.setNumEvents(num_events);
  lmd_runtime_config.setTotalElasticCrossSection(total_elastic_cross_section);

  lmd_runtime_config.setRawDataDirectory(input_dir_path);
  if (filelist_path != "")
    lmd_runtime_config.setRawDataFilelistPath(filelist_path);
  lmd_runtime_config.setDataOutputDirectory(output_dir_path);

  // set general config path
  lmd_runtime_config.setGeneralConfigDirectory(config_file_url);

  // read data parameter config
  boost::filesystem::path data_config_path(config_file_url);
  lmd_runtime_config.readDataConfig(data_config_path.filename().string());

  PndLmdDataFacade data_facade;

  PndLmdCombinedDataReader data_reader;
  if (!boost::filesystem::exists(lmd_runtime_config.getRawDataFilelistPath()))
    data_reader.addFilePath(lmd_runtime_config.getRawDataDirectory().string() +
                            "/Lumi_TrksQA*.root");
  else {
    data_reader.addFileList(
        lmd_runtime_config.getRawDataFilelistPath().string());
  }

  data_facade.createAndFillDataBundles(data_types, data_reader);

  std::cout << std::endl << std::endl;
  std::cout << "Application finished successfully." << std::endl;
  std::cout << std::endl;

  // ------------------------------------------------------------------------
}

void PndLmdDataFacade::createEfficiencies() {
  PndLmdAcceptance data_template;

  LumiFit::LmdDimension primary_dimension = constructDimensionFromConfig(
      lmd_runtime_config.getDataConfigTree().get_child(
          "efficiency.primary_dimension"));
  updateDimensionTypeInfoFromConfig(
      primary_dimension, lmd_runtime_config.getDataConfigTree().get_child(
                             "general_data.primary_dimension"));
  adjustDimensionDensity(primary_dimension,
                         constructDimensionFromConfig(
                             lmd_runtime_config.getDataConfigTree().get_child(
                                 "general_data.primary_dimension")));

  LumiFit::LmdDimension secondary_dimension = constructDimensionFromConfig(
      lmd_runtime_config.getDataConfigTree().get_child(
          "efficiency.secondary_dimension"));
  updateDimensionTypeInfoFromConfig(
      secondary_dimension, lmd_runtime_config.getDataConfigTree().get_child(
                               "general_data.secondary_dimension"));
  adjustDimensionDensity(secondary_dimension,
                         constructDimensionFromConfig(
                             lmd_runtime_config.getDataConfigTree().get_child(
                                 "general_data.secondary_dimension")));

  initializeData(data_template);

  applySelections();

  primary_dimension.dimension_options.track_type = LumiFit::MC;
  secondary_dimension.dimension_options.track_type = LumiFit::MC;
  data_template.setPrimaryDimension(primary_dimension);
  data_template.setSecondaryDimension(secondary_dimension);
  data_template.setName("lmd_acceptance");
  addMultipleInstancesBasedOnSelections(data_template);
}

void determineMomentumCut(TString dirname, unsigned int entries =100000) {
  TChain data_tree("cbmsim");

  TClonesArray* track_array;

  data_tree.Add(dirname + "/Lumi_TrksQA*.root");

  track_array = new TClonesArray("PndLmdTrackQ");
  data_tree.SetBranchAddress("LMDTrackQ", &track_array);
  data_tree.SetBranchStatus("LMDTrackQ*", 1);
  

  TH2D *mom = new TH2D("mom_cut_hist", "", 1000, -0.005, 0.005, 10000, 0.0, 0.2);

  if(data_tree.GetEntries() < entries)
    entries = data_tree.GetEntries();  

  for(unsigned int i = 0; i < entries; i++) {
    data_tree.GetEntry(i);

   //loop over track array
    for (Int_t iN = 0; iN < track_array->GetEntries(); iN++) {
      PndLmdTrackQ *track = (PndLmdTrackQ*)track_array->At(iN);
      // track status < 0 is a missed track
      if (0 > track->GetTrkRecStatus())
        continue;
      mom->Fill(track->GetMCtheta() - track->GetIPtheta(), (track->GetIPmom() - track->GetMCmom())/track->GetMCmom());
    }
  }

  mom->Draw("colz");
  TLine *cut = new TLine(-0.005, 0.0003, 0.005, 0.0003);
  cut->SetLineColor(2);
  cut->SetLineWidth(2.0);
  cut->Draw();
}

