    gPad->SetRightMargin(0.04);
    gPad->SetBottomMargin(0.12); 
    gPad->SetTopMargin(0.08); 
    gPad->SetTicks(1, 1);
    gPad->SetLogy();

    // Unify the vertical-axis range
    double yMax = 0;
