        yMax = hDataGen->GetMaximum() * 5.0; 
    } else {
        yMax = hDataRaw->GetMaximum() * 5.0; 
        if (hCorrectedHybrid && hCorrectedHybrid->GetMaximum() > yMax) yMax = hCorrectedHybrid->GetMaximum() * 5.0;
