    hEff->SetLineColor(kGreen+2);
    hEff->SetMarkerColor(kGreen+2);
    hEff->SetMarkerStyle(20);
    hEff->SetMarkerSize(4);
    hEff->SetLineWidth(4);

    hEffReco->SetLineColor(kOrange+7);
    hEffReco->SetMarkerColor(kOrange+7);
