            double scale = (physWidth > 0) ? (widthRef / physWidth) : 1.0; 
            
            hCorrectedHybridDisp->SetBinContent(i, hCorrectedHybrid->GetBinContent(i) * scale);
            hCorrectedHybridDisp->SetBinError(i, hCorrectedHybrid->GetBinError(i) * scale);
