 public:
  /** Default constructor **/
  PndFairHitQATask(std::string hitBranchName, std::string pointBranchName);

  /** Destructor **/
  virtual ~PndFairHitQATask();

  /** Virtual method Init **/
  virtual void SetParContainers();
  virtual InitStatus Init();

  /** Virtual method Exec **/
  virtual void Exec(Option_t *opt);
  virtual void FinishTask();
  void SetWorkdir(TString path) { fWorkdir = path; } ///< only needed to give cdash the path to the stored pictures

  void SetHitBranch(std::string hitBranch) { fHitBranchName = hitBranch; }
  void SetPointBranch(std::string pointBranch) { fPointBranchName = pointBranch; }
  void SetOutputPlotName(std::string val = "Output.gif") { fOutputPlotName = val; }

 protected:
  // These methods should be overwritten for a realistic test

  /**
   * @brief Initialize the histograms containing the measurement data in the histogram map
   */
  virtual void InitHistos();

  /**
   * @brief Set the name and the boundaries for a measurement to pass
   */
  virtual void SetAllBoundaries();

  /**
   * @brief Calculate the resolution of a FairHit based on the MC data from a FairMCPoint
   */
