    hEff->Draw("E");
    hEffReco->Draw("E SAME");

   /* // Physical visual lines
    TLine* l5 = new TLine(-30, 0, -30, 1.2);
    l5->SetLineStyle(2); l5->SetLineColor(kRed); l5->SetLineWidth(3); l5->Draw();
    TLine* l6 = new TLine(30, 0, 30, 1.2);
