Int_t RunSimulation(TString inputGenerator, TString particleType, TString simEngine = "TGeant3",
                    Int_t nEvents = 100, Double_t beamMomentum = 6.231552) {
  TStopwatch timer;
  timer.Start();

  TString parAsciiFile = "all.par";

  TString vmcdir = gSystem->Getenv("VMCWORKDIR");
  TString inFile = vmcdir + "/macro/QA/pid/RootSimFiles/" + particleType + "/" + particleType + ".root";\

  // -----   Create the Simulation run manager ------------------------------
  PndMasterRunSim *fRun = new PndMasterRunSim();
  fRun->SetInput(inputGenerator);
  fRun->SetName(simEngine);
  fRun->SetParamAsciiFile(parAsciiFile);
  fRun->SetNumberOfEvents(nEvents);
  fRun->SetBeamMom(beamMomentum);
  fRun->SetStoreTraj(kTRUE);
  // -----  Initialization   ------------------------------------------------
  fRun->Setup(inFile);
  // -----   Geometry   -----------------------------------------------------
  fRun->CreateGeometry();
  // -----   Event generator   ----------------------------------------------
  fRun->SetGenerator();
  // -----   Add tasks   ----------------------------------------------------
  fRun->AddSimTasks(); 
  // -----   Intialise and run   --------------------------------------------
  fRun->Init();
  fRun->Run(nEvents);
  fRun->Finish();


  timer.Stop();
  printf("RealTime=%f seconds\n", timer.RealTime());

  return 0;
}

