int py8_sim(Int_t nEvents = 1000, TString SimEngine = "TGeant3", Double_t BeamMomentum = 7.01, TString prefix = "py8", TString options = "")
{
  // There are to ways to use Pythia8: One is to set up a configuration string
  // as the "input" or just add the Generator by hand.
  //-----User Settings:------------------------------------------------------
  //  gDebug=5;
  TString parAsciiFile = "all.par";

  // if using the builtin setup, prepend "pythia8 and add a semicolon separated
  // list of your favourite configuration: "pythia8 SoftQCD:inelastic = on ; SomeOption = on"
  // the default is "SoftQCD:inelastic = on", if nothing is provided
  TString inputGenerator = "pythia8"; // Default background equal to "pythia8: SoftQCD:inelastic = on"

  //-------------------------------------------------------------------------
  // -----   Create the Simulation run manager ------------------------------
  PndMasterRunSim *fRun = new PndMasterRunSim();
  fRun->SetInput(inputGenerator);
  fRun->SetName(SimEngine);
  fRun->SetParamAsciiFile(parAsciiFile);
  fRun->SetNumberOfEvents(nEvents);
