    TH1D *projx = acchist2d->ProjectionX("xproj");
    TH1D *projy = acchist2d->ProjectionY("yproj");

    data[acc.first] =
        std::make_pair(1000.0 * projx->GetMean(), 1000.0 * projy->GetMean());
