/** PndDpmGenerator.h
 *@author S.Spataro <stefano.spataro@exp2.physik.uni-giessen.de>
 *
 The PndDpmGenerator reads the DPM output file (ROOT format)
 and inserts the tracks into the PndStack via the FairPrimaryGenerator.
 Derived from FairGenerator.
**/

#ifndef PND_DPMGENERATOR_H
#define PND_DPMGENERATOR_H

#include "FairGenerator.h"

class TClonesArray;
class TFile;
class TTree;
class TVirtualMCStack;
class FairPrimaryGenerator;

class PndDpmGenerator : public FairGenerator {

 public:
  /** Default constructor (should not be used) **/
  PndDpmGenerator();

  /** Standard constructor
   ** @param fileName The input (PLUTO) file name
   **/
  PndDpmGenerator(const Char_t *fileName);

  /** Destructor **/
  virtual ~PndDpmGenerator();

  /** Reads on event from the input file and pushes the tracks onto
   ** the stack. Abstract method in base class.
   ** @param primGen  pointer to the FairPrimaryGenerator
   **/
  virtual Bool_t ReadEvent(FairPrimaryGenerator *primGen);

  void SetStartEvent(Int_t start) { iEvent = start; };

 private:
  Int_t iEvent;             //! Event number
  const Char_t *fFileName;  //! Input file name
  TFile *fInputFile;        //! Pointer to input file
  TTree *fInputTree;        //! Pointer to input tree
  TClonesArray *fParticles; //! Particle array from PLUTO

  /** Private method CloseInput. Just for convenience. Closes the
   ** input file properly. Called from destructor and from ReadEvent. **/
  void CloseInput();

  ClassDef(PndDpmGenerator, 1);
};

#endif

// -------------------------------------------------------------------------
// -----                PndDpmGenerator source file                  -----
// -------------------------------------------------------------------------

#include <iostream>
#include "TClonesArray.h"
#include "TFile.h"
#include "TLorentzVector.h"
#include "TTree.h"
#include "TVector3.h"
#include "TParticle.h"
#include "PndDpmGenerator.h"
#include "FairPrimaryGenerator.h"

using namespace std;

// -----   Default constructor   ------------------------------------------
PndDpmGenerator::PndDpmGenerator()
{
  iEvent = 0;
  fInputFile = nullptr;
  fInputTree = nullptr;
}
// ------------------------------------------------------------------------

// -----   Standard constructor   -----------------------------------------
PndDpmGenerator::PndDpmGenerator(const Char_t *fileName)
{
  iEvent = 0;
  fFileName = fileName;
  fInputFile = new TFile(fFileName);
  fInputTree = (TTree *)fInputFile->Get("data");
  fParticles = new TClonesArray("TParticle", 100);
  fInputTree->SetBranchAddress("Particles", &fParticles);
}
// ------------------------------------------------------------------------

// -----   Destructor   ---------------------------------------------------
PndDpmGenerator::~PndDpmGenerator()
{
  CloseInput();
}
// ------------------------------------------------------------------------

// -----   Public method ReadEvent   --------------------------------------
Bool_t PndDpmGenerator::ReadEvent(FairPrimaryGenerator *primGen)
{

  // Check for input file
  if (!fInputFile) {
    cout << "-E PndDpmGenerator: Input file nor open!" << endl;
    return kFALSE;
  }

  // Check for number of events in input file
  if (iEvent > fInputTree->GetEntries()) {
    cout << "-E PndDpmGenerator: No more events in input file!" << endl;
    CloseInput();
    return kFALSE;
  }
  TFile *g = gFile;
  fInputFile->cd();
  fInputTree->GetEntry(iEvent++);
  g->cd();

  // Get number of particle in TClonesrray
  Int_t nParts = fParticles->GetEntriesFast();

  // Loop over particles in TClonesArray
  for (Int_t iPart = 0; iPart < nParts; iPart++) {
    TParticle *part = (TParticle *)fParticles->At(iPart);
    Int_t pdgType = part->GetPdgCode();

    // Check if particle type is known to database
    if (!pdgType) {
      cout << "-W PndDpmGenerator: Unknown type " << part->GetPdgCode() << ", skipping particle." << endl;
      continue;
    }

    Double_t px = part->Px();
    Double_t py = part->Py();
    Double_t pz = part->Pz();

    Double_t vx = part->Vx();
    Double_t vy = part->Vy();
    Double_t vz = part->Vz();

    // Give track to PrimaryGenerator
    primGen->AddTrack(pdgType, px, py, pz, vx, vy, vz);

  } //  Loop over particle in event

  return kTRUE;
}
// ------------------------------------------------------------------------

// -----   Private method CloseInput   ------------------------------------
void PndDpmGenerator::CloseInput()
{
  if (fInputFile) {
    cout << "-I PndDpmGenerator: Closing input file " << fFileName << endl;
    fInputFile->Close();
    delete fInputFile;
  }
  fInputFile = nullptr;
}
