int runMC_dpm(double mom, int mode = 0, int nevts = 10, TString fname = "")
{
  TStopwatch timer;
  timer.Start();
  gDebug = 0;

  // Load basic libraries
  gROOT->LoadMacro("$VMCWORKDIR/gconfig/basiclibs.C");
  basiclibs();
  // Load this example libraries
  gSystem->Load("libGeoBase");
  gSystem->Load("libParBase");
  gSystem->Load("libBase");
  gSystem->Load("libPndData");
  gSystem->Load("libField");
  gSystem->Load("libPassive");

  gSystem->Load("libMvd");
  gSystem->Load("libEmc");
  gSystem->Load("libDrcProp");
  gSystem->Load("libDrc");
  gSystem->Load("libGen");
  gSystem->Load("libDpmEvtGen");
  gSystem->Load("libPGen");
  gSystem->Load("libgenfit");
  gSystem->Load("libtrackrep");

  gSystem->Load("libtpc");
  gSystem->Load("libtpcreco");
  gSystem->Load("librecotasks");

  double mp = 0.938272;
  double p = 0, M = 0;

  // determine the pbar mom and E_cms for DPM generator
  if (mom > 0) {
    p = mom;
    double E = sqrt(mp * mp + mom * mom) + mp;
    M = sqrt(E * E - mom * mom);
  } else {
    M = -mom;
    double X = (M * M - 2 * mp * mp) / (2 * mp);
    p = sqrt(X * X - mp * mp);
  }

  char tmp[100];
  sprintf(tmp, "dpm%d_%6.4f_%dk", mode, M, nevts / 1000);
  if (fname == "")
    fname = TString(tmp);

  cout << "\n####### Basename: " << fname << "\n" << endl;
